CREATE OR REPLACE FUNCTION public.sync_user_email_identity_from_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
	IF NEW."email" IS NULL OR btrim(NEW."email") = '' THEN
		DELETE FROM "public"."user_email_identities"
		WHERE "user_email_identities"."user_id" = NEW."id";
		RETURN NEW;
	END IF;

	INSERT INTO "public"."user_email_identities" ("user_id", "normalized_email")
	VALUES (NEW."id", lower(btrim(NEW."email")))
	ON CONFLICT ("user_id") DO UPDATE
	SET "normalized_email" = EXCLUDED."normalized_email";

	RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_org_with_owner(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
	v_org_id uuid;
	v_org_name text;
	v_user_id uuid := auth.uid();
BEGIN
	IF v_user_id IS NULL THEN
		RAISE EXCEPTION 'Authentication required to create an organization';
	END IF;

	v_org_name := btrim(p_name);
	IF v_org_name IS NULL OR v_org_name = '' THEN
		RAISE EXCEPTION 'Organization name is required';
	END IF;

	IF char_length(v_org_name) > 100 THEN
		RAISE EXCEPTION 'Organization name must be 100 characters or fewer';
	END IF;

	INSERT INTO public.organizations (name, created_by)
	VALUES (v_org_name, v_user_id)
	RETURNING id INTO v_org_id;

	INSERT INTO public.organization_memberships (
		organization_id,
		user_id,
		role,
		member_preset,
		capability_overrides,
		access_scope_kind,
		access_scope_group_ids
	)
	VALUES (
		v_org_id,
		v_user_id,
		'owner',
		'editor',
		'{}'::jsonb,
		'organization',
		ARRAY[]::uuid[]
	);

	RETURN v_org_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_organization_rank_catalog_org_move()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW."organization_id" IS DISTINCT FROM OLD."organization_id" THEN
    RAISE EXCEPTION 'organization_rank_catalog.organization_id cannot be changed'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.storage_object_org_id(object_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  folder_parts text[];
BEGIN
  folder_parts := storage.foldername(object_name);

  IF array_length(folder_parts, 1) IS NULL OR array_length(folder_parts, 1) < 1 THEN
    RETURN NULL;
  END IF;

  BEGIN
    RETURN folder_parts[1]::uuid;
  EXCEPTION
    WHEN others THEN
      RETURN NULL;
  END;
END;
$function$

